-- Gainora’s own Capture & Convert: hello@gainora.co.uk’s settings (src/lib/gainora-line.ts).
-- The receptionist answers for Gainora, and the free 15-minute diagnostic call is booked into this diary with Adelin,
-- by phone or on the booking page (capture.gainora.co.uk/book/gainora, shown on gainora.co.uk/book). Only the
-- thank-you, booking confirmation and reminder texts are on. Also makes sure hello@ has Capture & Convert switched on.
-- The previous settings, if any, come back in the result.
with u as (select id from auth.users where lower(email) = 'hello@gainora.co.uk'),
old as (select s.data from public.capture_settings s join u on s.user_id = u.id),
access as (
  insert into public.entitlements (email, user_id, agent, status, plan)
  select 'hello@gainora.co.uk', id, 'capture', 'active', 'book' from u
  on conflict (email, agent) do update set user_id = excluded.user_id, status = 'active', plan = coalesce(public.entitlements.plan, excluded.plan), updated_at = now()
  returning id
),
saved as (
  insert into public.capture_settings (user_id, data, completed_at, updated_at)
  select id, jsonb_set($gainora${"business":{"kind":"appointments","name":"Gainora","ownerName":"Adelin","trade":"Business growth and automation","location":"United Kingdom","website":"https://gainora.co.uk","phone":"","alertEmail":"hello@gainora.co.uk","alertMobile":""},"work":{"services":"Capture & Convert: a receptionist that answers every call, and follow-ups that send themselves\nLaunch & Grow: website, Google Business Profile, reviews and ads\nCommand Centre: a weekly watch on the business and a plain-English brief\nGrowth & Operations Partner: fixing how the business runs\nBusiness Audit","notDone":"Legal, accounting, tax or regulatory advice\nMarketing messages to people who haven’t asked for them","areas":"Anywhere in the UK, by phone and video"},"calls":{"days":[1,2,3,4,5],"open":"09:00","close":"16:30","emergencies":"","transferTo":"","quotePolicy":"fixed","priceNotes":"","booking":"calendar","gasWork":false,"recording":true,"notify":"all","greeting":"Hello, you’re through to Gainora. How can I help?","announceAi":false,"safety":"","emergencyLine":"","transferEmergency":false,"alertText":"urgent"},"bookings":{"system":"Gainora diary (this app)","systemOther":"","account":"Gainora","mode":"book","address":"By phone or video","arrival":"","types":[{"name":"15-minute diagnostic call","minutes":15,"price":"Free","who":"Adelin"}],"staff":"Adelin","noticeHours":2,"aheadWeeks":4,"cancellation":"If the time stops working, just reply to your confirmation and we’ll move it.","deposit":"","depositLink":"","depositOn":false,"status":"connected"},"followUps":{"reviewLink":"","payLink":"","paymentDays":0},"provider":{"name":"Retell","aiNumber":""},"automations":{"ack":{"on":true,"since":"2026-11-10T00:00:00.000Z","steps":{"ack":{"on":true,"channel":"text","ask":false,"text":"Hi {first name}, thanks for calling Gainora. Your message is with Adelin. If you’d like a free 15-minute call, just reply here or book at gainora.co.uk.","subject":"Thanks for calling Gainora","wait":0}}},"booking":{"on":true,"since":"2026-11-10T00:00:00.000Z","steps":{"confirm":{"on":true,"channel":"text","ask":false,"text":"Hi {first name}, you’re booked in for a free 15-minute call with {who} from Gainora on {day} {date} at {time}. He’ll ring you on this number, or send a video link if you asked for one. Need to move it? Just reply to this message.","subject":"Your call with Gainora is booked","wait":0},"reminder":{"on":true,"channel":"text","ask":false,"text":"Hi {first name}, a reminder of your free call with {who} from Gainora {when} at {time}. Reply to this message if you need to move it.","subject":"A reminder of your call with Gainora","wait":1}}},"quote":{"on":false,"since":"2026-11-10T00:00:00.000Z","steps":{"chase1":{"on":true,"channel":"text","ask":false,"text":"Hi {first name}, just checking the quote[ for {amount}] reached you. Happy to answer any questions or adjust anything. {owner}, {business}","subject":"Your quote from {business}","wait":3},"chase2":{"on":true,"channel":"text","ask":false,"text":"Hi {first name}, I won’t keep chasing. If you’d like to go ahead later, just reply here and I’ll get you booked in. Thanks, {owner}, {business}","subject":"Your quote from {business}","wait":8}}},"payment":{"on":false,"since":"2026-11-10T00:00:00.000Z","steps":{"pay1":{"on":true,"channel":"text","ask":false,"text":"Hi {first name}, a friendly reminder that {amount} for your recent [{appointment} ]booking with {business} is due {due}.[ You can pay here: {pay link}] Thank you!","subject":"Payment reminder from {business}","wait":0},"pay2":{"on":true,"channel":"text","ask":false,"text":"Hi {first name}, our records show {amount} is still outstanding. If you’ve already paid, thank you and please ignore this.[ You can pay here: {pay link}] If something’s not right, just reply and we’ll sort it. {business}","subject":"Payment reminder from {business}","wait":7},"pay3":{"on":true,"channel":"text","ask":true,"text":"Hi {first name}, {amount} is now overdue. Could you let us know when it will be paid, or reply if there’s a problem we can sort out together?[ {pay link}] {owner}, {business}","subject":"Overdue payment: {business}","wait":14}}},"review":{"on":false,"since":"2026-11-10T00:00:00.000Z","steps":{"review":{"on":true,"channel":"text","ask":false,"text":"Hi {first name}, thank you for visiting {business}. We hope you’re feeling the benefit.[ If you have a minute, a Google review really helps us: {review link}]","subject":"Thank you from {business}","wait":1}}},"aftercare":{"on":false,"since":"2026-11-10T00:00:00.000Z","steps":{"checkin":{"on":true,"channel":"text","ask":false,"text":"Hi {first name}, just checking in after your [{appointment} ]appointment at {business}. We hope you’re happy! If anything doesn’t feel quite right, reply here[ or call us on {phone}] and we’ll help.","subject":"How are you getting on?","wait":1}}},"rebook":{"on":false,"since":"2026-11-10T00:00:00.000Z","steps":{"rebook":{"on":true,"channel":"text","ask":false,"text":"Hi {first name}, it’s been a little while since your [{appointment} ]appointment at {business}. Would you like to book your next one? Just reply here[ or call us on {phone}].","subject":"Time for your next appointment?","wait":42}}}},"texting":{"number":"","status":"off"},"page":{"on":true,"slug":"gainora","mode":"book","intro":"A free call about what isn’t working. Adelin asks the questions that matter and tells you honestly which package fits, or whether none does. By phone or video, whichever you prefer.","showPrices":true,"types":[],"chooseStaff":false,"accent":"#7A6436"},"diary":{"step":30,"buffer":30},"completedAt":"2026-11-10T00:00:00.000Z"}$gainora$::jsonb, '{completedAt}', to_jsonb(now())), now(), now() from u
  on conflict (user_id) do update set data = excluded.data, completed_at = excluded.completed_at, updated_at = now()
  returning user_id
)
select (select count(*) from u) as account_found, (select count(*) from access) as access_on, (select count(*) from saved) as saved, (select data from old) as previous_settings;
